#!/usr/bin/env bashset -euo pipefailAPP_DIR="${APP_DIR:-/opt/charm}"BACKUP_DIR="${BACKUP_DIR:-$APP_DIR/backups}"BACKUP_ENV="${BACKUP_ENV:-$APP_DIR/.backup.env}"DATE="$(date +%Y-%m-%d_%H-%M-%S)"DB_BACKUP="$BACKUP_DIR/db/charm-db-$DATE.dump"CONTENT_BACKUP="$BACKUP_DIR/content/charm-content-$DATE.tar.gz"if [ ! -f "$BACKUP_ENV" ]; then  echo "Backup env file not found: $BACKUP_ENV" >&2  exit 1fisource "$BACKUP_ENV"mkdir -p "$BACKUP_DIR/db" "$BACKUP_DIR/content"cd "$APP_DIR"echo "[$(date)] Starting PostgreSQL backup"docker exec charm-postgres sh -c \  'pg_dump -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Fc' \  > "$DB_BACKUP"echo "[$(date)] PostgreSQL backup saved: $DB_BACKUP"echo "[$(date)] Starting content backup"docker exec charm-back sh -c \  'tar -czf - -C "$APP_CONTENT_BASE_PATH" .' \  > "$CONTENT_BACKUP"echo "[$(date)] Content backup saved: $CONTENT_BACKUP"echo "[$(date)] Uploading backup to S3 via restic"restic backup "$DB_BACKUP" "$CONTENT_BACKUP"echo "[$(date)] Applying restic retention policy"restic forget \  --keep-daily 14 \  --keep-weekly 8 \  --keep-monthly 12 \  --pruneecho "[$(date)] Removing local backups older than 14 days"find "$BACKUP_DIR/db" -type f -name "*.dump" -mtime +14 -deletefind "$BACKUP_DIR/content" -type f -name "*.tar.gz" -mtime +14 -deleteecho "[$(date)] Backup finished"